ssp.poiManager.show(p.id);`,iH=["POI 必须已 add 过 (在当前页面生命周期内)","hide 不销毁, 可以再 show 回来","remove 是销毁 (show 不回来)"],oH=["createPoi","createPoiNode"],rH=["poi","show","hide","toggle"],aH={id:WV,category:qV,subcategory:XV,intent:ZV,scene:YV,sdk:KV,method:JV,signature:QV,params:eH,returns:tH,code:nH,example:sH,guard:iH,seeAlso:oH,tags:rH},cH="showPoi",lH="poi",dH="visibility",uH=["显示 POI","显示标记点","show poi"],hH="3D",pH="ssp-shim",fH="ssp.poiManager.show",mH="show(id: string): boolean",gH=[{name:"id",type:"string",required:!0,desc:"已创建 POI 的 id"}],yH="是否找到并显示 POI",_H="const poi = ssp.poiManager.list()[0]; if (!poi) console.warn('no poi'); else console.log('show poi', poi.id, ssp.poiManager.show(poi.id));",bH="ssp.poiManager.show('poi_1');",vH=["POI 必须已在当前页面生命周期创建"],xH=["createPoi","hidePoi","removePoi"],TH=["poi","show","visibility"],SH={id:cH,category:lH,subcategory:dH,intent:uH,scene:hH,sdk:pH,method:fH,signature:mH,params:gH,returns:yH,code:_H,example:bH,guard:vH,seeAlso:xH,tags:TH},wH="clear",AH="scene",EH="root",MH=["清空场景","清掉所有对象","reset scene","重置场景"],RH="3D",CH="ssp-shim",IH="ssp.sceneTool.clear",PH="clear(keepCameraLight?: boolean): void",OH=[{name:"keepCameraLight",type:"boolean",required:!1,default:"true",desc:"是否保留相机和光源 (默认保留,避免黑屏)"}],LH="void",DH="ssp.sceneTool.clear(true);",NH=`/* 场景化清空, 推荐配合重载 */

/* 1) 软清空: 保留相机/光源, 只清模型 */
ssp.sceneTool.clear(true);

/* 2) 硬清空: 连相机/光源也清 (场景会变黑) */
ssp.sceneTool.clear(false);

/* 3) 切换场景: clear + loadSubcategory */
ssp.sceneTool.clear();
const infos = await ssp.modelTool.loadSubcategory('hospital');
console.log('loaded', infos.length, 'GLB');`,UH=["默认 keepCameraLight=true, 避免黑屏","清完后对象仍可访问, 但已 dispose, 不能 add 回场景","切场景: clear + loadSubcategory, 不要只 clear 不加载"],FH=["scene","clear","reset"],kH={id:wH,category:AH,subcategory:EH,intent:MH,scene:RH,sdk:CH,method:IH,signature:PH,params:OH,returns:LH,code:DH,example:NH,guard:UH,tags:FH},zH="dispose",$H="scene",BH="root",VH=["销毁 GPU 资源","dispose","释放 GPU 资源","释放 mesh","释放材质","释放几何"],HH="3D",GH="ssp-shim",jH="ssp.sceneTool.dispose",WH="dispose(): void",qH=[],XH="void",ZH="ssp.sceneTool.dispose();",YH=`/* 释放场景中所有 mesh 的 GPU 资源 (geometry / material) */
ssp.sceneTool.dispose();
console.log('all geometries and materials disposed');

