// ssp.sceneTool.dispose(); // 释放 GPU 资源 (清完后 dispose 是必须的, 否则泄漏)

/* 不要在 clear 前 dispose, 否则对象还在 scene 但 GPU 资源已释放 */`,KH=["只释放 GPU 资源 (geometry/material), 不清空场景对象, 不影响 window.ssp","不可逆: 调完后 mesh 无法渲染, 必须清掉 scene","切场景: dispose → clear → loadSubcategory","多次调用安全 (重复 dispose 已经被 dispose 的资源会 warning)"],JH=["clear"],QH=["destroy","lifecycle","gpu"],eG={id:zH,category:$H,subcategory:BH,intent:VH,scene:HH,sdk:GH,method:jH,signature:WH,params:qH,returns:XH,code:ZH,example:YH,guard:KH,seeAlso:JH,tags:QH},tG="help",nG="scene",sG="help",iG=["帮助","你能做什么","怎么使用 AI 场景助手"],oG="template.help",rG="help(): TemplateResult",aG=!0,cG=[],lG="{ message }",dG="return { message: '可查询、统计、高亮、聚焦、隐藏或隔离场景对象，也可控制主视角和楼层炸开。' };",uG="return { message: '显示帮助' };",hG=["该模板不访问 SSP，只返回能力说明"],pG=["ai","help"],fG={id:tG,category:nG,subcategory:sG,intent:iG,method:oG,signature:rG,aiEnabled:aG,params:cG,returns:lG,code:dG,example:uG,guard:hG,tags:pG},mG="setBackgroundColor",gG="scene",yG="root",_G=["设置背景颜色","改背景","换底色","天空背景","change bg","bg color"],bG="3D",vG="ssp-shim",xG="ssp.sceneTool.setBackgroundColor",TG="setBackgroundColor(color: string | number): void",SG=[{name:"color",type:"string | number",required:!0,desc:"颜色 — hex 字符串 ('#000033') / CSS 名 ('black') / 0xRRGGBB 数字",examples:["'#0a0a1a'","'#87ceeb' (sky blue)","0x101218"]}],wG="void",AG="ssp.sceneTool.setBackgroundColor('#0a0a1a');",EG=`/* 几种常见背景 */

/* 深色 (默认风格) */
ssp.sceneTool.setBackgroundColor('#0a0a1a');

/* 蓝天 (白天建筑可视化) */
ssp.sceneTool.setBackgroundColor('#87ceeb');

/* 黑色 (拍电影感) */
ssp.sceneTool.setBackgroundColor(0x000000);

/* 配合雾化看深度 */
ssp.sceneTool.setBackgroundColor('#0a0a1a');
ssp.sceneTool.setFog({ color: '#0a0a1a', near: 100, far: 500 });`,MG=["颜色立即生效, 不带 transition","要淡入淡出请自己用 tween 工具 (ssp.animationTool.addTween 暂未实现)","深色背景建议同时设雾色一致, 避免边缘突兀"],RG=["setFog"],CG=["background","color","sky"],IG={id:mG,category:gG,subcategory:yG,intent:_G,scene:bG,sdk:vG,method:xG,signature:TG,params:SG,returns:wG,code:AG,example:EG,guard:MG,seeAlso:RG,tags:CG},PG="setFog",OG="scene",LG="root",DG=["设置雾效","雾化","fog"],NG="3D",UG="ssp-shim",FG="ssp.sceneTool.setFog",kG="setFog(options?: { color?, near?, far?, visible? }): void",zG=[{name:"options",type:"{ color?: IColor, near?: number, far?: number, visible?: boolean }",required:!1}],$G="void",BG="ssp.sceneTool.setFog({ color: '#aaccff', near: 100, far: 800, visible: true });",VG="ssp.sceneTool.setFog({ color: 0xcce0ff, near: 200, far: 1200, visible: true });",HG=["不传则使用 SceneMetadata.json 中的 fog 配置"],GG=["setBackgroundColor"],jG=["fog","atmosphere"],WG={id:PG,category:OG,subcategory:LG,intent:DG,scene:NG,sdk:UG,method:FG,signature:kG,params:zG,returns:$G,code:BG,example:VG,guard:HG,seeAlso:GG,tags:jG},qG="update",XG="scene",ZG="root",YG=["刷新场景","强制重渲染","render update","触发 camera-controls 重算"],KG="3D",JG="ssp-shim",QG="ssp.sceneTool.update",e8="update(): void",t8=[],n8="void",s8="ssp.sceneTool.update();",i8=`/* 实际上 Three.js renderer 在每帧 RAF 自动渲染, sceneTool.update() 是 noop 占位 */

